Setter (Değiştirici), veriyi değiştirmeden önce kuralları denetleyen bekçidir:

class BankaHesabi:
    # ...
    def para_yatir(self, miktar):
        if miktar > 0:
            self.__bakiye += miktar
            print(f'{miktar} TL yatırıldı. Yeni bakiye: {self.__bakiye} TL')
        else:
            print('HATA: Yatırılacak tutar 0\'dan büyük olmalıdır!')

class BankaHesabi:
    # ...
    def para_cek(self, miktar):
        if 0 < miktar <= self.__bakiye:
            self.__bakiye -= miktar
            print(f'{miktar} TL çekildi. Kalan: {self.__bakiye} TL')
        else:
            print('HATA: Yetersiz bakiye veya geçersiz tutar!')

class NakitOdeme:
    def ode(self, tutar):
