    def ode(self, tutar):
        print(f'💳 {self.kart_no} nolu karttan {tutar:.2f} TL çekildi.')

class KampusKartOdeme:
    def __init__(self, ogrenci_no):
        self.ogrenci_no = ogrenci_no

    def ode(self, tutar):
        print(f'🎓 {self.ogrenci_no} nolu öğrenci kartından {tutar:.2f} TL temassız çekildi.')

class Cuzdan:
    def __init__(self, sahip, para):
        self.sahip = sahip
        self.__para = 0.0
        if para > 0:
            self.__para = para

    def para_harca(self, miktar):
        if miktar <= self.__para:
            self.__para -= miktar
            print(f'{miktar} TL harcandı. Kalan: {self.__para} TL')
        else:
            print('Cüzdanda yeterli para yok!')

