class OgrenciNot:
    def __init__(self, ad):
        self.ad = ad
        self.__vize = 0

    def vize_gir(self, not_degeri):
        if 0 <= not_degeri <= 100:
            self.__vize = not_degeri
            print(f'{self.ad} vize notu: {self.__vize}')
        else:
            print('HATA: Not 0 ile 100 arasında olmalıdır!')

